content.text:
            headers.append((name, value.strip(' \t')))
            name = None
            value = None
        i = 0
        while i < len(text) and text[i] in TOKEN_CHARS:
            i += 1
        if i == 0:
            raise WireError('syntax')
        raw_name = text[:i]
        j = i
        while j < len(text) and text[j] in ' \t':
            j += 1
        if j >= len(text) or text[j] != ':':
            raise WireError('syntax')
        name = raw_name.lower()
        value = text[j + 1:]
    if name is not None:
        headers.append((name, value.strip(' \t')))
    return [(COMPACT.get(n, n), v) for n, v in headers]


def parse_request(data):
    """Parse one request; return a dict of fields or raise WireError."""
    if len(data) > MAX_REQUEST_BYTES:
        raise WireError('syntax')
    index = data.find(b'\r\n\r\n')
    if index < 0:
        raise WireError('syntax')
    block = data[:index]
    body = data[index + 4:]
    if len(block) > MAX_HEADER_BLOCK_BYTES:
        raise WireError('syntax')

    lines = split_header_lines(block)
    if not lines:
        raise WireError('syntax')
    if len(lines) - 1 > MAX_HEADER_LINES:
        raise WireError('syntax')

    start = lines[0].decode('latin-1')
    parts = start.split(' ')
    if len(parts) != 3:
        raise WireError('syntax')
    method, uri_text, version = parts
    if method not in ('INVITE', 'MESSAGE'):
        raise WireError('syntax')
    if version != 'SIP/2.0':
        raise WireError('syntax')
    target = parse_uri(uri_text)
    if target is None or uri_kind(target) != 'sip':
        raise WireError('syntax')

    headers = parse_header_fields(lines)

    counts = {}
    for name, _ in headers:
        counts[name] = counts.get(name, 0) + 1
    for required in REQUIRED_SINGLETONS:
        if counts.get(required, 0) != 1:
            raise WireError('headers')

    values = {}
    rows = {}
    for name, value in headers:
        if name in REQUIRED_SINGLETONS:
            values[name] = value
        else:
            rows.setdefault(name, []).append(value)

    length_text = values['content-length']
    if not (1 <= len(length_text) <= 10):
        raise WireError('length')
    for ch in length_text:
        if ch not in DIGITS:
            raise WireError('length')
    if int(length_text) != len(body):
        raise WireError('length')

    # ---- field grammar -------------------------------------------------
    from_info = parse_from_header(values['from'])
    if from_info is None:
        raise WireError('fields')
    from_uri, tag = from_info
    to_uri = parse_address(values['to'])
    if to_uri is None or uri_kind(to_uri) != 'sip':
        raise WireError('fields')
    if to_uri != target:
        raise WireError('fields')

    call_id = values['call-id']
    if not CALLID_RE.match(call_id):
        raise WireError('fields')

    cseq_match = CSEQ_RE.match(values['cseq'])
    if cseq_match is None:
        raise WireError('fields')
    cseq_number = int(cseq_match.group(1))
    if cseq_number < 1 or cseq_number > 2147483647:
        raise WireError('fields')
    if cseq_match.group(2) != method:
        raise WireError('fields')

    asserted = parse_identity_list(rows.get('p-asserted-identity'))
    preferred = parse_identity_list(rows.get('p-preferred-identity'))
    privacy = parse_privacy(rows.get('privacy'))

    return {
        'method': method,
        'target': target,
        'from_uri': from_uri,
        'tag': tag,
        'call_id': call_id,
        'cseq': cseq_number,
        'asserted': asserted,
        'preferred': preferred,
        'privacy': privacy,
        'body': body,
    }


def parse_from_header(value):
    """Parse the From header; return (canonical From URI, tag) or None."""
    semi = find_unquoted(value, ';')
    if semi is None:
        return None
    address = value[:semi].strip(' \t')
    params = value[semi + 1:].strip(' \t')
    uri = parse_address(address)
    if uri is None:
        return None
    match = TAG_RE.match(params)
    if match is None:
        return None
    tag = match.group(1)
    if not (1 <= len(tag) <= 32):
        return None
    return uri, tag


